begin;
alter table public.tasks add column completed_at timestamptz;
create function private.task_completion() returns trigger language plpgsql set search_path='' as $$begin if new.status='completed' and (tg_op='INSERT' or old.status is distinct from 'completed') then new.completed_at=now();elsif new.status<>'completed' then new.completed_at=null;else new.completed_at=old.completed_at;end if;return new;end$$;
create trigger task_completion before insert or update on public.tasks for each row execute function private.task_completion();
-- Existing completion dates remain unknown; no fabricated history is backfilled.
drop policy jobs_cancel_only on public.jarvis_jobs;
create policy jobs_cancel_only on public.jarvis_jobs as restrictive for update to authenticated using(status in ('draft','scheduled','retry','processing')) with check(status='cancelled');
create function public.my_usage() returns jsonb language plpgsql security definer set search_path='' as $$begin if not public.account_allowed() then raise exception 'Access denied' using errcode='42501';end if;return (select jsonb_build_object('requests',count(*),'tokens',coalesce(sum(coalesce(input_tokens,0)+coalesce(output_tokens,0)),0),'usd',coalesce(sum(coalesce(cost_usd,reserved_usd)),0),'uncertain',count(*) filter(where status in ('reserved','uncertain')),'daily_usd',coalesce(sum(case when created_at>=date_trunc('day',now() at time zone 'UTC') at time zone 'UTC' then coalesce(cost_usd,reserved_usd) else 0 end),0)) from public.ai_usage where user_id=auth.uid() and created_at>=date_trunc('month',now() at time zone 'UTC') at time zone 'UTC');end$$;
create function public.movie_notification_needed() returns boolean language sql security definer set search_path='' as $$select exists(select 1 from public.ai_policy p join public.ai_preferences a on a.user_id=p.user_id where p.movie_notifications and p.notification_consent and a.notifications_enabled and private.user_allowed(p.user_id) and not exists(select 1 from public.user_notifications n where n.user_id=p.user_id and n.dedupe_key='movie:'||(now() at time zone p.timezone)::date))$$;
create function public.enqueue_movie_notification(film_title text) returns void language sql security definer set search_path='' as $$insert into public.user_notifications(user_id,kind,title,body,dedupe_key) select p.user_id,'movie','Günün filmi',left(film_title,200),'movie:'||(now() at time zone p.timezone)::date from public.ai_policy p join public.ai_preferences a on a.user_id=p.user_id where p.movie_notifications and p.notification_consent and a.notifications_enabled and private.user_allowed(p.user_id) on conflict(user_id,dedupe_key) do nothing$$;
revoke all on function public.my_usage() from public,anon;grant execute on function public.my_usage() to authenticated;
revoke all on function public.movie_notification_needed(),public.enqueue_movie_notification(text),private.task_completion() from public,anon,authenticated;
grant execute on function public.movie_notification_needed(),public.enqueue_movie_notification(text) to service_role;
commit;
